// 기본사용법은 breakpoint 설정후 
// step over --> 한번에 함수를 실행하고 넘김
// step in --> 함수 내부로 들어가 한 줄씩 실행
// ===========================
// 1) 프로시저 (함수)
// ===========================

// Apps Script에서는 VBA의 프로시저 대신 JavaScript 함수를 사용합니다
// 함수 선언 방식
function myFunction() {
  Logger.log("기본 함수입니다");
}

// 매개변수가 있는 함수
function calculateSum(a, b) {
  return a + b;
}

// 값을 반환하는 함수
function getToday() {
  return new Date();
}

// 함수 호출 예제
function callFunctions() {
  myFunction();
  var sum = calculateSum(5, 3);
  var today = getToday();
  Logger.log("합계: " + sum);
  Logger.log("오늘 날짜: " + today);
}

// ===========================
// 2) 변수
// ===========================

// 변수의 선언 방법과 범위(scope)에 대한 예제 함수
function variableExamples() {

  // 변수 선언 방법
  var name = "홍길동";    // var: 함수 내 어디서든 접근 가능 (함수 스코프)
  let age = 30;          // let: { } 블록 내부에서만 접근 가능
  const PI = 3.14159;    // const: 상수 선언 (값을 변경할 수 없음)

  // 지역 변수 예시 (함수 스코프)
  function localScopeExample() {
    var localVar = "로컬 변수";  // 함수 내부에서만 사용 가능한 지역 변수
    return localVar;             // 지역 변수 값을 반환
  }

  // 전역 변수 예시 (전체 스크립트에서 접근 가능)
  var globalVar = "전역 변수";

  // 변수의 값 출력
  Logger.log(name);                 // "홍길동" 출력
  Logger.log(age);                  // 30 출력
  Logger.log(PI);                   // 3.14159 출력
  Logger.log(localScopeExample());  // "로컬 변수" 출력 (함수를 실행한 결과)
  Logger.log(globalVar);            // "전역 변수" 출력
}

// ===========================
// 3) 자료형
// ===========================

function dataTypeExamples() {
  // 기본 자료형
  var text = "문자열";           // 문자열(String)
  var number = 123;             // 숫자(Number)
  var decimal = 3.14;           // 소수(Number)
  var isTrue = true;            // 논리값(Boolean)
  var nothing = null;           // Null
  var notDefined;               // Undefined

  // 복합 자료형
  var array = [1, 2, 3, 4, 5];              // 배열(Array)
  var person = {name: "김철수", age: 25};     // 객체(Object)
  var today = new Date();                    // 날짜(Date)

  // 자료형 확인
  Logger.log("text의 타입: " + typeof text);
  Logger.log("number의 타입: " + typeof number);
  Logger.log("isTrue의 타입: " + typeof isTrue);
  Logger.log("array의 타입: " + typeof array);
  Logger.log("array는 배열입니까? " + Array.isArray(array));
  Logger.log("person의 타입: " + typeof person);
  Logger.log("today의 타입: " + typeof today);
}

// ===========================
// 4) 연산자
// ===========================

function operatorExamples() {
  // 산술 연산자
  var a = 10;
  var b = 3;

  Logger.log("더하기: " + (a + b));      // 13
  Logger.log("빼기: " + (a - b));        // 7
  Logger.log("곱하기: " + (a * b));      // 30
  Logger.log("나누기: " + (a / b));      // 3.3333...
  Logger.log("나머지: " + (a % b));      // 1
  Logger.log("증가: " + (++a));          // 11
  Logger.log("감소: " + (--b));          // 2

  // 비교 연산자
  Logger.log("a == b: " + (a == b));     // false
  Logger.log("a != b: " + (a != b));     // true
  Logger.log("a > b: " + (a > b));       // true
  Logger.log("a < b: " + (a < b));       // false
  Logger.log("a >= b: " + (a >= b));     // true
  Logger.log("a <= b: " + (a <= b));     // false

  // 논리 연산자
  var x = true;
  var y = false;

  Logger.log("x && y: " + (x && y));     // false
  Logger.log("x || y: " + (x || y));     // true
  Logger.log("!x: " + (!x));             // false

  // 대입 연산자
  var c = 5;
  c += 2;  // c = c + 2
  Logger.log("c += 2: " + c);            // 7

  c -= 1;  // c = c - 1
  Logger.log("c -= 1: " + c);            // 6

  c *= 3;  // c = c * 3
  Logger.log("c *= 3: " + c);            // 18

  c /= 2;  // c = c / 2
  Logger.log("c /= 2: " + c);            // 9
}

// ===========================
// 5) 제어문_조건문
// ===========================

function conditionalExamples() {
  var score = 85;

  // if문
  if (score >= 90) {
    Logger.log("A 등급");
  } else if (score >= 80) {
    Logger.log("B 등급");
  } else if (score >= 70) {
    Logger.log("C 등급");
  } else if (score >= 60) {
    Logger.log("D 등급");
  } else {
    Logger.log("F 등급");
  }

  // 삼항 연산자
  var result = (score >= 60) ? "합격" : "불합격";
  Logger.log("시험 결과: " + result);

  // switch문
  var day = new Date().getDay();
  switch (day) {
    case 0:
      Logger.log("일요일");
      break;
    case 1:
      Logger.log("월요일");
      break;
    case 2:
      Logger.log("화요일");
      break;
    case 3:
      Logger.log("수요일");
      break;
    case 4:
      Logger.log("목요일");
      break;
    case 5:
      Logger.log("금요일");
      break;
    case 6:
      Logger.log("토요일");
      break;
    default:
      Logger.log("알 수 없는 요일");
  }
}

// ===========================
// 6) 제어문_반복문
// ===========================

function loopExamples() {
  // for 루프
  Logger.log("for 루프:");
  for (var i = 0; i < 5; i++) {
    Logger.log("반복 횟수: " + i);
  }

  // while 루프
  Logger.log("while 루프:");
  var count = 0;
  while (count < 3) {
    Logger.log("카운트: " + count);
    count++;
  }

  // do-while 루프
  Logger.log("do-while 루프:");
  var num = 1;
  do {
    Logger.log("숫자: " + num);
    num++;
  } while (num <= 3);

  // forEach (배열 전용)
  Logger.log("forEach 루프:");
  var fruits = ["사과", "바나나", "오렌지"];
  fruits.forEach(function(fruit, index) {
    Logger.log(index + ": " + fruit);
  });

  // for...in (객체 속성 순회)
  Logger.log("for...in 루프:");
  var person = {name: "이영희", age: 28, job: "개발자"};
  for (var key in person) {
    Logger.log(key + ": " + person[key]);
  }
  // in은 객체(object)에서만 사용할 수 있다.
  for (var value in person) {
    Logger.log("value : " + value);
  }


  // for...of (ES6, 반복 가능한 객체 순회)
  Logger.log("for...of 루프:");
  var colors = ["빨강", "파랑", "초록"];
  for (var color of colors) {
    Logger.log(color);
  }

  // for...in (배열에는 index를 추출한다, 권장되지 않는다.))
  Logger.log("for...in 루프:");
  var colors = ["빨강", "파랑", "초록"];
  for (var color in colors) {
    Logger.log(color);
  }
}

// ===========================
// 7) 배열
// ===========================

function arrayExamples() {
  // 배열 선언 및 초기화
  var numbers = [1, 2, 3, 4, 5];
  var empty = [];
  var mixed = [1, "텍스트", true, {name: "김민수"}];

  // 배열 요소 접근
  Logger.log("첫 번째 요소: " + numbers[0]);
  Logger.log("두 번째 요소: " + numbers[1]);

  // 배열 길이
  Logger.log("배열 길이: " + numbers.length);

  // 배열 요소 추가
  numbers.push(6);           // 배열 끝에 추가
  Logger.log("push 후: " + numbers);

  numbers.unshift(0);        // 배열 앞에 추가
  Logger.log("unshift 후: " + numbers);

  // 배열 요소 제거
  var last = numbers.pop();  // 배열 끝 요소 제거
  Logger.log("pop 된 요소: " + last);
  Logger.log("pop 후: " + numbers);

  var first = numbers.shift(); // 배열 첫 요소 제거
  Logger.log("shift 된 요소: " + first);
  Logger.log("shift 후: " + numbers);

  // 배열 메서드
  var fruits = ["사과", "바나나", "오렌지", "포도"];

  // 배열 슬라이스
  var someFruits = fruits.slice(1, 3);
  Logger.log("slice 결과: " + someFruits);

  // 배열 연결
  var moreFruits = fruits.concat(["키위", "망고"]);
  Logger.log("concat 결과: " + moreFruits);

  // 요소 인덱스 찾기
  var index = fruits.indexOf("오렌지");
  Logger.log("오렌지의 인덱스: " + index);

  // 배열 요소 연결
  var fruitString = fruits.join(", ");
  Logger.log("join 결과: " + fruitString);

  // 배열 정렬
  fruits.sort();
  Logger.log("sort 결과: " + fruits);

  // 배열 역순 정렬
  fruits.reverse();
  Logger.log("reverse 결과: " + fruits);
}

// ===========================
// 11) 인덱싱 및 슬라이싱
// ===========================

function indexingAndSlicingExamples() {
  // 문자열 인덱싱
  var text = "Google Apps Script";
  Logger.log("원본 문자열: " + text);

  // 문자열 개별 문자 접근 (인덱싱)
  Logger.log("첫 번째 문자: " + text[0]);           // G
  Logger.log("두 번째 문자: " + text[1]);           // o
  Logger.log("여섯 번째 문자: " + text[5]);         // e
  Logger.log("마지막 문자: " + text[text.length - 1]); // t

  // 문자열 슬라이싱 (substring, slice)
  Logger.log("처음부터 6글자: " + text.substring(0, 6));    // Google
  Logger.log("7번째부터 끝까지: " + text.substring(7));     // Apps Script
  Logger.log("7번째부터 11번째까지: " + text.substring(7, 11)); // Apps

  // slice도 substring과 유사하지만 음수 인덱스 지원
  Logger.log("뒤에서 6글자: " + text.slice(-6));    // Script
  Logger.log("처음부터 -7까지: " + text.slice(0, -7)); // Google Apps

  // 배열 인덱싱
  var fruits = ["사과", "바나나", "오렌지", "망고", "포도"];
  Logger.log("과일 배열: " + fruits);

  // 배열 개별 요소 접근 (인덱싱)
  Logger.log("첫 번째 과일: " + fruits[0]);               // 사과
  Logger.log("세 번째 과일: " + fruits[2]);               // 오렌지
  Logger.log("마지막 과일: " + fruits[fruits.length - 1]); // 포도

  // 배열 슬라이싱 (slice)
  Logger.log("처음 두 과일: " + fruits.slice(0, 2));      // ["사과", "바나나"]
  Logger.log("두 번째부터 네 번째까지: " + fruits.slice(1, 4)); // ["바나나", "오렌지", "망고"]
  Logger.log("세 번째부터 끝까지: " + fruits.slice(2));    // ["오렌지", "망고", "포도"]
  Logger.log("마지막 두 과일: " + fruits.slice(-2));       // ["망고", "포도"]

  // 2차원 배열 (행렬) 인덱싱
  var matrix = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
  ];
  Logger.log("행렬: " + JSON.stringify(matrix));

  // 2차원 배열 요소 접근
  Logger.log("첫 번째 행, 두 번째 열: " + matrix[0][1]);  // 2
  Logger.log("두 번째 행, 세 번째 열: " + matrix[1][2]);  // 6
  Logger.log("세 번째 행, 첫 번째 열: " + matrix[2][0]);  // 7

  // 2차원 배열 행 슬라이싱
  var secondRow = matrix[1];
  Logger.log("두 번째 행: " + secondRow);            // [4, 5, 6]

  // 특정 행의 일부분 슬라이싱
  var partOfThirdRow = matrix[2].slice(0, 2);
  Logger.log("세 번째 행의 처음 두 요소: " + partOfThirdRow); // [7, 8]

  // 스프레드시트 범위 인덱싱 및 슬라이싱 (참고용)
  if (SpreadsheetApp.getActiveSpreadsheet()) {
    var sheet = SpreadsheetApp.getActiveSheet();

    // 데이터 설정 (예시)
    sheet.getRange("A1:C3").setValues([
      ["이름", "나이", "직업"],
      ["김철수", 30, "교사"],
      ["이영희", 28, "개발자"]
    ]);

    // 범위 인덱싱 (특정 셀 가져오기)
    var b2Value = sheet.getRange(2, 2).getValue();  // B2 셀 (30)
    Logger.log("B2 셀 값: " + b2Value);

    // 범위 슬라이싱 (행/열 단위로 가져오기)
    var firstRowValues = sheet.getRange(1, 1, 1, 3).getValues()[0];  // 첫 번째 행
    Logger.log("첫 번째 행: " + firstRowValues);

    var secondColumnValues = sheet.getRange(1, 2, 3, 1).getValues().map(row => row[0]);  // 두 번째 열
    Logger.log("두 번째 열: " + secondColumnValues);

    // 부분 범위 슬라이싱
    var subRangeValues = sheet.getRange(2, 1, 2, 2).getValues();  // A2:B3 영역
    Logger.log("부분 범위(A2:B3): " + JSON.stringify(subRangeValues));
  }

  // 객체 속성 인덱싱
  var person = {
    name: "김민수",
    age: 35,
    job: "프로그래머",
    address: {
      city: "서울",
      district: "강남구"
    }
  };

  // 점 표기법으로 속성 접근
  Logger.log("이름: " + person.name);          // 김민수
  Logger.log("직업: " + person.job);           // 프로그래머

  // 대괄호 표기법으로 속성 접근 (동적 속성명에 유용)
  var property = "age";
  Logger.log("나이: " + person[property]);     // 35

  // 중첩 객체 속성 접근
  Logger.log("도시: " + person.address.city);  // 서울

  // 객체 키 배열 가져오기
  var keys = Object.keys(person);
  Logger.log("객체 키: " + keys);              // ["name", "age", "job", "address"]

  // 객체 값 배열 가져오기
  var values = Object.values(person);
  Logger.log("객체 값: " + JSON.stringify(values));

  // 객체 항목(키-값 쌍) 배열 가져오기
  var entries = Object.entries(person);
  Logger.log("객체 항목: " + JSON.stringify(entries));
}

// ===========================
// 8) 내장함수
// ===========================

function builtInFunctionExamples() {
  // 문자열 관련 함수
  var text = "  Hello, World!  ";
  Logger.log("원본 텍스트: '" + text + "'");
  Logger.log("길이: " + text.length);
  Logger.log("대문자: " + text.toUpperCase());
  Logger.log("소문자: " + text.toLowerCase());
  Logger.log("공백 제거: '" + text.trim() + "'");
  Logger.log("부분 문자열: " + text.substring(3, 8));
  Logger.log("문자 위치: " + text.indexOf("World"));
  Logger.log("문자 교체: " + text.replace("World", "Apps Script"));

  // 숫자 관련 함수
  Logger.log("절대값: " + Math.abs(-5));
  Logger.log("올림: " + Math.ceil(4.3));
  Logger.log("내림: " + Math.floor(4.7));
  Logger.log("반올림: " + Math.round(4.5));
  Logger.log("최댓값: " + Math.max(1, 5, 3, 8, 2));
  Logger.log("최솟값: " + Math.min(1, 5, 3, 8, 2));
  Logger.log("거듭제곱: " + Math.pow(2, 3));
  Logger.log("제곱근: " + Math.sqrt(16));
  Logger.log("난수(0-1): " + Math.random());
  Logger.log("1에서 10 사이 난수: " + Math.floor(Math.random() * 10 + 1));

  // 날짜 관련 함수
  var now = new Date();
  Logger.log("현재 날짜: " + now);
  Logger.log("연도: " + now.getFullYear());
  Logger.log("월(0-11): " + now.getMonth());
  Logger.log("일: " + now.getDate());
  Logger.log("요일(0-6): " + now.getDay());
  Logger.log("시: " + now.getHours());
  Logger.log("분: " + now.getMinutes());
  Logger.log("초: " + now.getSeconds());

  // 타입 변환 함수
  Logger.log("문자를 숫자로: " + parseInt("42"));
  Logger.log("소수 문자를 숫자로: " + parseFloat("3.14"));
  Logger.log("숫자를 문자로: " + String(42));
  Logger.log("값을 불리언으로: " + Boolean(1));
}

// ===========================
// 9) 오류처리
// ===========================

function errorHandlingExamples() {
  // try-catch로 오류 처리
  try {
    // 오류가 발생할 수 있는 코드
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("존재하지 않는 시트");
    sheet.getRange("A1").setValue("테스트");
  } catch (error) {
    // 오류 발생 시 실행되는 코드
    Logger.log("오류 발생: " + error.message);
  } finally {
    // 오류 발생 여부와 관계없이 항상 실행되는 코드
    Logger.log("finally 블록 실행됨");
  }

  // 오류 발생시키기
  function divideNumbers(a, b) {
    if (b === 0) {
      throw new Error("0으로 나눌 수 없습니다");
    }
    return a / b;
  }

  // 오류 처리 테스트
  try {
    var result1 = divideNumbers(10, 2);
    Logger.log("10 / 2 = " + result1);

    var result2 = divideNumbers(10, 0);
    Logger.log("10 / 0 = " + result2);  // 이 라인은 실행되지 않음
  } catch (error) {
    Logger.log("나눗셈 오류: " + error.message);
  }
}
